'use client'

import { useReducedMotion } from 'motion/react'
import { useEffect, useRef } from 'react'

/**
 * 签名水印（首页右下角背景装饰）：
 * 按笔画顺序将手写签名 SVG "画"出来——stroke-dashoffset 从全长递减到 0。
 * 关键机制：
 * - SVG 的 stroke dash 序列跨子路径连续累计，因此单个 <path> 内多个分离笔画段
 *   （签名导出时的 m 子路径）会按顺序逐段描边，天然实现"一笔接一笔"。
 * - 3 个 <path> 用 JS 时间轴依次衔接：每笔按笔画数计时（单笔固定时长），
 *   前一笔画画到 STAGGER_OVERLAP 时下一笔开始，有轻微重叠、运笔连贯。
 * - 单次播放：画一遍后保持（fill: both 定格终态），不循环重画。
 * - 开场由 JS 淡入（FADE_IN_MS）到 WATERMARK_OPACITY，规避刷新后的"停顿"。
 * - 颜色用 currentColor 继承文字色，明暗主题自动适配。
 * - 尊重 prefers-reduced-motion：直接静态展示最终签名。
 *
 * 参数（FADE_IN_MS / MS_PER_STROKE / MIN_DRAW_MS / STAGGER_OVERLAP）
 * 为用户手动调校过的值，改动前须与用户确认。
 */
const SIGN_PATHS = [
  // path 1：签名首笔
  'M2525 5042 c-6 -4 2 -19 19 -37 20 -21 27 -24 22 -11 -6 17 -2 18 34 13 58 -8 253 -142 386 -267 24 -23 44 -37 44 -33 0 14 -158 155 -254 225 -136 101 -216 136 -251 110z',
  // path 2：主体（内含多个 m 笔画段，按 d 顺序逐段描边）
  'M2570 4912 c0 -4 7 -39 15 -77 22 -101 63 -413 80 -610 8 -93 17 -200 21 -236 l7 -66 -49 -33 c-27 -18 -116 -80 -197 -139 -81 -58 -158 -113 -170 -121 -13 -8 -87 -64 -166 -125 -78 -60 -152 -116 -162 -124 -15 -11 -11 3 18 58 35 68 37 74 22 99 -12 22 -23 28 -60 30 -91 6 -165 -40 -503 -314 -50 -40 -50 -27 0 44 73 102 269 350 294 372 15 13 220 271 249 313 65 96 15 126 -105 61 -280 -151 -595 -518 -776 -904 -26 -55 -91 -214 -111 -272 -5 -15 -10 -16 -34 -7 -15 7 -64 11 -108 11 -125 -1 -288 -60 -431 -157 -46 -31 -62 -32 -34 -2 12 12 35 40 52 62 29 39 29 40 1 9 -166 -183 -269 -316 -341 -442 -43 -75 -49 -92 -33 -92 13 0 25 17 88 121 123 206 208 289 388 381 136 69 283 102 376 84 60 -11 61 -15 35 -97 -13 -40 -29 -98 -36 -128 -16 -69 -23 -75 -440 -388 -271 -202 -325 -253 -269 -253 43 0 281 161 460 311 35 30 95 78 133 108 l69 54 -6 -34 c-3 -19 -13 -65 -22 -104 -21 -97 -40 -196 -69 -365 -14 -80 -32 -185 -41 -235 -8 -49 -29 -137 -46 -194 -16 -57 -28 -110 -25 -118 4 -8 16 -13 28 -11 19 2 30 22 65 118 99 271 249 787 289 994 12 60 24 94 38 108 30 28 175 125 327 219 128 78 132 80 145 60 32 -45 140 -32 245 30 28 16 53 28 56 26 3 -4 -52 -139 -128 -316 -24 -56 -25 -91 -1 -91 17 1 30 16 167 195 39 50 84 109 102 131 18 21 47 57 65 80 145 181 303 350 341 365 18 7 57 23 87 36 67 30 153 63 156 60 1 -1 -27 -33 -63 -72 -36 -38 -77 -86 -91 -105 -15 -19 -29 -37 -32 -40 -16 -15 -90 -122 -114 -162 -30 -51 -28 -68 8 -68 29 0 70 33 196 154 86 82 178 156 194 156 3 0 6 -18 6 -40 0 -33 -9 -52 -48 -103 -75 -97 -154 -225 -147 -236 13 -22 35 -10 82 46 26 32 54 64 61 72 7 8 20 24 29 37 8 13 19 24 23 24 4 0 10 -42 14 -92 35 -495 75 -952 128 -1463 16 -162 21 -280 22 -515 1 -322 -3 -364 -55 -541 -21 -72 -78 -204 -85 -197 -5 6 72 290 92 337 17 40 18 51 3 51 -20 0 -58 -100 -169 -458 -27 -84 -35 -100 -46 -91 -11 9 -14 7 -14 -9 0 -11 11 -27 24 -36 24 -15 26 -15 56 22 42 51 122 218 160 332 61 188 86 452 70 735 -13 226 -36 518 -54 690 -21 190 -77 851 -91 1075 -3 41 -8 107 -10 147 l-6 71 47 69 c93 135 186 213 254 213 23 0 30 -4 30 -20 0 -47 56 -37 120 21 90 81 273 189 320 189 6 0 10 -52 9 -127 -1 -123 -3 -151 -28 -308 -13 -79 -61 -255 -97 -358 -13 -38 -22 -73 -18 -78 17 -29 59 5 302 245 324 320 439 422 625 556 121 87 153 104 393 214 l80 37 49 -48 c41 -41 50 -45 53 -29 6 30 -45 149 -79 184 -36 37 -71 49 -190 64 -72 10 -111 9 -227 -5 -119 -15 -284 -45 -343 -63 -13 -4 -18 5 -23 43 -24 167 -118 300 -263 369 -100 48 -178 59 -285 41 -124 -21 -361 -123 -517 -221 -22 -14 -42 -26 -44 -26 -2 0 -48 -29 -103 -65 -54 -36 -102 -65 -105 -65 -4 0 -10 35 -13 78 -39 477 -79 769 -117 869 -8 21 -29 33 -29 15z m1115 -613 c68 -18 119 -45 173 -94 92 -83 139 -173 149 -284 l5 -57 -133 -33 c-74 -18 -167 -41 -207 -51 l-73 -18 -17 37 c-9 20 -24 45 -33 56 -9 11 -19 29 -22 40 -3 11 -5 -19 -6 -68 -1 -86 -2 -88 -28 -98 -28 -11 -220 -72 -338 -108 -33 -10 -132 -44 -220 -74 -88 -31 -161 -54 -163 -52 -2 2 4 17 12 34 24 46 20 71 -12 83 l-29 11 -9 145 -9 146 40 29 c59 43 297 183 384 227 240 120 412 162 536 129z m-1755 -284 c0 -31 -92 -157 -274 -375 -171 -205 -325 -408 -333 -438 -15 -62 42 -42 167 59 235 190 359 269 421 269 54 0 48 -40 -23 -145 -59 -87 -96 -120 -373 -335 -223 -172 -392 -308 -435 -349 -13 -13 -16 -9 -22 34 -4 31 -16 57 -33 75 -26 27 -26 27 -9 71 9 24 25 63 35 86 10 24 19 45 19 48 0 16 110 232 161 316 83 139 137 213 235 325 98 112 88 102 210 209 93 82 205 155 236 155 10 0 18 -2 18 -5z m2796 -131 c47 -24 63 -47 48 -71 -6 -10 -65 -45 -130 -78 -127 -64 -225 -118 -260 -144 -12 -9 -32 -23 -44 -31 -51 -34 -241 -188 -330 -269 -125 -114 -109 -99 -333 -318 -107 -106 -199 -193 -205 -193 -5 0 5 55 23 123 18 67 40 168 50 225 17 96 25 116 40 92 9 -15 72 -12 104 4 96 50 271 335 338 551 l18 60 135 27 c182 37 275 47 402 44 79 -3 116 -8 144 -22z m-2023 -160 l7 -120 -43 -21 c-54 -26 -154 -101 -260 -196 -46 -41 -96 -77 -112 -81 -16 -4 -54 -18 -83 -32 -29 -13 -54 -24 -57 -24 -20 0 -365 -167 -486 -235 -34 -20 -63 -34 -65 -32 -7 7 131 171 218 260 93 93 112 109 348 284 69 50 136 101 150 111 38 29 195 139 285 200 94 64 88 71 98 -114z m1280 39 c-31 -112 -174 -365 -255 -453 -58 -63 -115 -89 -133 -61 -3 6 13 60 36 121 22 62 43 127 46 146 7 44 -15 79 -62 95 -24 9 -35 19 -35 34 0 11 -3 30 -6 42 -5 20 1 24 68 43 40 11 96 27 123 35 136 39 192 54 212 54 21 1 21 1 6 -56z m-439 -79 c3 -9 6 -27 6 -40 0 -20 -5 -24 -29 -24 -39 0 -149 -57 -256 -134 -88 -63 -90 -64 -119 -49 -56 29 -157 -5 -243 -81 -42 -38 -53 -42 -93 -41 l-45 1 0 68 0 68 80 29 c113 42 489 167 555 186 139 38 136 38 144 17z m84 -116 c18 -18 14 -55 -18 -148 l-29 -85 -1 123 c0 111 2 122 18 122 10 0 23 -5 30 -12z m-915 -46 c4 -38 1 -44 -22 -56 -35 -19 -254 -106 -257 -103 -8 9 264 212 273 204 1 -1 3 -21 6 -45z m11 -129 c11 -71 8 -101 -14 -108 -32 -10 -169 -117 -254 -199 -43 -42 -81 -74 -83 -72 -5 4 15 47 26 56 3 3 21 28 40 55 71 103 249 305 270 305 4 0 11 -17 15 -37z m86 -121 c0 -5 -9 -17 -20 -27 -20 -18 -20 -17 -20 8 0 20 5 27 20 27 11 0 20 -4 20 -8z m-542 -21 c-1 -4 -38 -46 -80 -92 -78 -86 -264 -313 -370 -452 -33 -43 -62 -77 -64 -74 -4 4 11 43 46 122 120 267 123 275 98 275 -6 0 -34 -18 -62 -40 -99 -75 -228 -119 -255 -86 -11 13 -5 20 41 50 89 57 528 266 592 282 14 3 29 10 32 15 7 11 27 12 22 0z m-568 -95 c0 -2 -16 -21 -35 -42 -20 -22 -57 -68 -83 -102 -39 -53 -66 -76 -162 -134 -124 -77 -223 -142 -308 -202 -30 -20 -56 -35 -60 -32 -3 3 -3 8 -1 10 28 24 435 347 499 395 47 35 98 74 113 87 28 23 37 28 37 20z m1030 -53 c-1 -11 -61 -76 -65 -71 -5 4 53 78 61 78 2 0 4 -3 4 -7z m-1720 -332 c5 -11 10 -42 10 -69 0 -45 -3 -51 -39 -80 -50 -40 -63 -41 -51 -4 44 142 55 172 61 172 5 0 13 -9 19 -19z m-20 -181 c-319 -260 -650 -514 -689 -527 -17 -6 -16 -6 238 192 288 223 380 295 393 308 25 24 73 56 83 56 6 0 -6 -13 -25 -29z m5 -77 c-11 -61 -102 -421 -130 -513 -15 -47 -31 -101 -36 -120 -6 -19 -14 -46 -19 -60 -5 -14 -23 -72 -40 -128 -17 -57 -33 -102 -36 -100 -2 3 3 40 11 84 8 43 24 142 35 219 20 138 66 376 97 508 14 59 23 74 61 108 25 21 49 39 54 39 5 0 6 -17 3 -37z',
  // path 3：收尾短笔
  'M394 3327 c10 -7 43 -32 72 -56 30 -24 56 -42 59 -39 8 8 -38 65 -72 86 -18 12 -43 22 -55 21 -22 0 -22 -1 -4 -12z',
]

/** 水印整体透明度（画完保持时的可见度） */
const WATERMARK_OPACITY = 0.3
/** 开场淡入时长（ms）：播放一次，画完保持不循环 */
const FADE_IN_MS = 1500
/** 每笔动画时长（ms）：按笔画数计时，单笔固定时长 */
const MS_PER_STROKE = 2000
/** 最短单笔时长，避免过短笔段一闪而过 */
const MIN_DRAW_MS = 1000
/** 下一笔在前一笔画到该比例时开始（轻微重叠，运笔连贯） */
const STAGGER_OVERLAP = 0.4

export function SignatureWatermark({ className }: { className?: string }) {
  const svgRef = useRef<SVGSVGElement>(null)
  const reduce = useReducedMotion()

  useEffect(() => {
    const svg = svgRef.current
    if (!svg) return

    if (reduce) {
      // 减弱动效：静态展示最终签名
      svg.querySelectorAll('path').forEach((p) => {
        p.style.strokeDashoffset = '0'
        p.style.fillOpacity = '1'
      })
      svg.style.opacity = String(WATERMARK_OPACITY)
      return
    }

    const paths = Array.from(svg.querySelectorAll('path'))
    const anims: Animation[] = []
    let cursor = 0

    const runCycle = () => {
      // 重置初始态
      paths.forEach((p) => {
        const len = p.getTotalLength()
        p.style.strokeDashoffset = String(len)
        p.style.fillOpacity = '0'
      })

      cursor = 0
      const lengthAnims: Animation[] = []
      paths.forEach((p) => {
        const len = p.getTotalLength()
        // 按笔画数计时：path 内每个 m/M 子路径视为一笔，单笔固定时长。
        // 签名导出时主体是一个含多个 m 子笔画段的超长 path（周长差异可达几十倍），
        // 统一按长度计时会让短笔瞬间完成、长笔要画几分钟；按笔画数才能节奏均匀。
        const strokes = (p.getAttribute('d') ?? '').match(/[mM]/g)?.length ?? 1
        const dur = Math.max(MIN_DRAW_MS, strokes * MS_PER_STROKE)
        const anim = p.animate(
          [
            { strokeDashoffset: len, fillOpacity: 0 },
            { strokeDashoffset: 0, fillOpacity: 0, offset: 0.65 },
            { strokeDashoffset: 0, fillOpacity: 1, offset: 0.9 },
            { strokeDashoffset: 0, fillOpacity: 1 },
          ],
          { duration: dur, delay: cursor, easing: 'ease-out', fill: 'both' },
        )
        lengthAnims.push(anim)
        cursor += dur * STAGGER_OVERLAP
      })
      anims.push(...lengthAnims)
    }

    // 开场淡入（JS）：规避刷新后到动画启动前的"停顿"
    const fade = svg.animate(
      [
        { opacity: 0 },
        { opacity: WATERMARK_OPACITY, offset: 0.1 },
        { opacity: WATERMARK_OPACITY },
      ],
      { duration: FADE_IN_MS, easing: 'ease-out', fill: 'both' },
    )
    anims.push(fade)

    // 单次播放：画一遍后保持（fill: both 定格终态），不循环重画
    runCycle()

    return () => {
      anims.forEach((a) => a.cancel())
    }
  }, [reduce])

  return (
    <svg
      ref={svgRef}
      viewBox="0 0 492 507"
      aria-hidden
      className={className}
      style={{ opacity: 0 }}
    >
      <g
        transform="translate(0,507) scale(0.1,-0.1)"
        fill="currentColor"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinejoin="round"
      >
        {SIGN_PATHS.map((d, i) => (
          <path
            key={i}
            d={d}
            style={{
              fillOpacity: 0,
              strokeDasharray: '1000',
              strokeDashoffset: 1000,
            }}
          />
        ))}
      </g>
    </svg>
  )
}
